CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, title TEXT NOT NULL, quadrant TEXT NOT NULL, status TEXT NOT NULL, category TEXT NOT NULL, dueTime TEXT NOT NULL, isTopThree INTEGER NOT NULL, createdAt INTEGER NOT NULL);
CREATE TABLE habits (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, title TEXT NOT NULL, iconName TEXT NOT NULL, targetDaysPerWeek INTEGER NOT NULL, currentStreak INTEGER NOT NULL, isCompletedToday INTEGER NOT NULL, category TEXT NOT NULL);
CREATE TABLE timetable_entries (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, courseCode TEXT NOT NULL, courseName TEXT NOT NULL, dayOfWeek INTEGER NOT NULL, startHour INTEGER NOT NULL, startMinute INTEGER NOT NULL, endHour INTEGER NOT NULL, endMinute INTEGER NOT NULL, room TEXT NOT NULL, professor TEXT NOT NULL, colorHex INTEGER NOT NULL);
CREATE TABLE assignments (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, courseCode TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, dueDateMillis INTEGER NOT NULL, isSubmitted INTEGER NOT NULL, weightPercentage INTEGER NOT NULL, category TEXT NOT NULL);
CREATE TABLE attendance_records (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, courseCode TEXT NOT NULL, attendedClasses INTEGER NOT NULL, totalClasses INTEGER NOT NULL, targetPercentage INTEGER NOT NULL);
CREATE TABLE fitness_logs (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, splitName TEXT NOT NULL, dateMillis INTEGER NOT NULL, durationMinutes INTEGER NOT NULL, completedExercisesCount INTEGER NOT NULL, totalExercisesCount INTEGER NOT NULL, isCompleted INTEGER NOT NULL);
CREATE TABLE exercise_sets (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, exerciseName TEXT NOT NULL, splitCategory TEXT NOT NULL, setNumber INTEGER NOT NULL, reps INTEGER NOT NULL, weightKg REAL NOT NULL, isCompleted INTEGER NOT NULL, timestamp INTEGER NOT NULL);
CREATE TABLE body_weight_logs (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, weightKg REAL NOT NULL, note TEXT NOT NULL, timestamp INTEGER NOT NULL);
CREATE TABLE water_logs (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, amountMl INTEGER NOT NULL, timestamp INTEGER NOT NULL);
CREATE TABLE daily_resets (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, dateString TEXT NOT NULL, mood TEXT NOT NULL, brainDump TEXT NOT NULL, triagedTasksCount INTEGER NOT NULL, gearPacked INTEGER NOT NULL, completedAt INTEGER NOT NULL);
